<script setup lang="ts">
import {ref,watch} from 'vue'
import SiteDialog from '@/features/management-shared/SiteDialog.vue'
import {getTeacherExperimentApi,type ClassTask} from '@/features/teacher-experiments/api'
import type {AdminRow} from './api'
const props=defineProps<{row?:AdminRow}>(),emit=defineEmits<{close:[];changed:[]}>(),api=getTeacherExperimentApi(),task=ref<ClassTask>(),error=ref(''),mode=ref('detail'),busy=ref(false),opens=ref(''),closes=ref(''),reason=ref('')
function local(v:string|null){if(!v)return '';const d=new Date(v);return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16)}
async function load(){if(!props.row)return;try{task.value=await api.task(Number(props.row.id));opens.value=local(task.value.opens_at);closes.value=local(task.value.closes_at)}catch(e){error.value=(e as Error).message}}
watch(()=>props.row,()=>{task.value=undefined;mode.value='detail';reason.value='';error.value='';void load()},{immediate:true})
async function save(){if(!task.value)return;busy.value=true;error.value='';try{if(mode.value==='close')await api.manualClose(task.value.id,reason.value);else await api.reviseSchedule(task.value.id,{expected_revision:task.value.schedule_revision,reopen:['manual_closed','closed'].includes(task.value.business_status),reason:reason.value,...(task.value.available_actions.includes('revise_schedule')&&opens.value!==local(task.value.opens_at)?{opens_at:opens.value?new Date(opens.value).toISOString():null}:{}),...(closes.value!==local(task.value.closes_at)?{closes_at:closes.value?new Date(closes.value).toISOString():null}:{})});await load();mode.value='detail';emit('changed')}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
</script>
<template><SiteDialog :open="Boolean(row)" :title="mode==='schedule'?'调整班级任务排期':mode==='close'?'提前结束班级任务':row?.experiment_name||'班级任务'" :subtitle="row?.class_name" @close="emit('close')"><p v-if="!task&&!error" role="status">正在读取任务状态…</p><template v-if="task"><template v-if="mode==='detail'"><dl class="detail-list"><div><dt>任务状态</dt><dd>{{ row?.status_label||task.business_status }}</dd></div><div><dt>开始时间</dt><dd>{{ task.opens_at||'未设置' }}</dd></div><div><dt>截止时间</dt><dd>{{ task.closes_at||'未设置' }}</dd></div><div><dt>发布参与人数</dt><dd>{{ task.participant_count }}</dd></div><div><dt>排期版本</dt><dd>{{ task.schedule_revision }}</dd></div></dl><div class="action-grid"><button v-if="task.available_actions.some(x=>['revise_schedule','adjust_time'].includes(x))" @click="mode='schedule'">调整排期</button><button v-if="task.available_actions.includes('manual_close')" class="danger" @click="mode='close'">提前结束任务</button></div></template><form v-else id="task-change" class="form-grid" @submit.prevent="save"><template v-if="mode==='schedule'"><label class="field">开始时间<input v-model="opens" type="datetime-local" :disabled="!task.available_actions.includes('revise_schedule')"></label><label class="field">截止时间<input v-model="closes" type="datetime-local"></label></template><p v-else>提前结束仅影响当前班级任务。其他班级的排期与作答保持不变。</p><label class="field">变更原因<textarea v-model="reason" required rows="3" /></label></form></template><p v-if="error" class="error-block" role="alert">{{ error }}</p><template #footer><button @click="emit('close')">关闭</button><button v-if="mode!=='detail'" class="primary" form="task-change" type="submit" :disabled="busy">{{ busy?'正在提交…':'确认变更' }}</button></template></SiteDialog></template>
